// 4 - Mask patient identifiers before any model sees them.
// Only the masked text goes to OpenAI or Anthropic; the original stays in your database behind staff permissions.
const item = $('1 - New Intake Item or Document From the Staff Portal').first().json.body;
const role = $input.first().json;
let text = String(item.document_text || '');
for (const name of [item.patient_display_name].filter(Boolean)) text = text.split(name).join('[NAME]');
const rules = [
  [/\b\d{1,2}[\/.-]\d{1,2}[\/.-]\d{2,4}\b/g, '[DATE]'],
  [/\b\d{3}-\d{2}-\d{4}\b/g, '[SSN]'],
  [/(?:\+?1[\s.-]?)?\(?\b\d{3}\)?[\s.-]?\d{3}[\s.-]?\d{4}\b/g, '[PHONE]'],
  [/[\w.+-]+@[\w-]+\.[\w.-]+/g, '[EMAIL]'],
  [/\b(?:member|subscriber|mrn|account)\s*(?:id|no\.?|number|#)\s*[:#]?\s*(?=[A-Z0-9-]*\d)[A-Z0-9-]{5,}/gi, '[MEMBER_ID]'],
];
for (const [pattern, tag] of rules) text = text.replace(pattern, tag);
return [{ json: {
  item_id: item.item_id,
  staff_user_id: item.staff_user_id,
  staff_role: role.role,
  service_line: item.service_line || 'all',
  document_type_hint: item.document_type_hint || 'none',
  masked_text: text.slice(0, 12000),
} }];

// KB 2 - Split the saved document into passages, each tagged with doc, version and section.
// Headings start a new passage; long sections are cut at about 1,200 characters with a small overlap.
const doc = $('KB 1 - Admin Saves or Edits a Policy, SOP, Form or Guideline').first().json.body;
const MAX = 1200, OVERLAP = 150;
const blocks = String(doc.text || '').split(/\n(?=#{1,3} )/);
const passages = [];
for (const block of blocks) {
  const body = block.trim();
  const heading = (body.split('\n')[0] || '').replace(/^#+\s*/, '').slice(0, 120);
  for (let start = 0; start < body.length; start += MAX - OVERLAP) {
    const content = body.slice(start, start + MAX);
    if (content.trim().length < 40) continue;
    const n = passages.length;
    passages.push({ idx: n, chunk_id: doc.doc_id + '-v' + doc.version + '-c' + String(n + 1).padStart(2, '0'), section_heading: heading, content });
  }
}
return [{ json: { doc_id: doc.doc_id, version: doc.version, passages, inputs: passages.map(p => doc.doc_title + ' | ' + p.section_heading + '\n' + p.content) } }];

