// 12 - One audit row per action the system took on this intake item.
// It reads which steps actually ran, so a refused run, a fallback run and a review run each log exactly what happened.
const N = {
  intake: '1 - New Intake Item or Document From the Staff Portal',
  role: '2 - Look Up the Staff Role, Mark the Item In Progress',
  refused: '3b - Refuse: Role Not Allowed to Submit Intake',
  search: '6 - Supabase: Find the Matching Policy, SOP and Form Passages',
  claude: '8 - Claude Triages Using Only Your Documents',
  fallback: '9b - OpenAI Fallback: Same Rules, Same Sources',
  task: '11 - Your Internal Tools API: Create the Task in the Right Queue',
  review: '11b - Add It to the Human Review Queue',
};
const ran = (name) => { try { return $(name).isExecuted; } catch (e) { return false; } };
const out = (name) => (ran(name) ? $(name).first().json : {});
const intake = out(N.intake).body || {};
const passages = out(N.search).passages || [];
const base = { item_id: intake.item_id, staff_user_id: intake.staff_user_id, execution_id: $execution.id, model: null, confidence: null, source_ids: [] };
const rows = [{ ...base, action: 'intake_received', outcome: 'ok', detail: intake.document_type_hint || 'no hint' }];

if (ran(N.refused)) {
  rows.push({ ...base, action: 'permission_check', outcome: 'refused', detail: 'role not allowed to submit intake' });
} else {
  rows.push({ ...base, action: 'permission_check', outcome: 'allowed', detail: out(N.role).role });
  rows.push({ ...base, action: 'identifiers_masked', outcome: 'ok', detail: 'masked before any model call' });
  rows.push({ ...base, action: 'knowledge_retrieved', outcome: ran(N.claude) ? 'matched' : 'no_match', source_ids: passages.map(p => p.chunk_id), detail: 'top similarity ' + Number(out(N.search).top_similarity || 0).toFixed(2) });
  for (const [name, model, action] of [[N.claude, 'claude', 'ai_triage'], [N.fallback, 'openai', 'ai_triage_fallback']]) {
    if (!ran(name)) continue;
    const r = out(name);
    rows.push({ ...base, action, model, outcome: r.output ? 'answered' : 'failed', confidence: r.output ? r.output.confidence : null, source_ids: r.output ? r.output.cited_chunk_ids : [], detail: r.output ? r.output.category : String(r.error || 'no output').slice(0, 200) });
  }
  if (ran(N.task)) rows.push({ ...base, action: 'task_routed', outcome: 'routed', detail: 'task ' + (out(N.task).id || out(N.task).task_id) });
  if (ran(N.review)) rows.push({ ...base, action: 'sent_to_human_review', outcome: 'needs_review', detail: out(N.review).reason_code });
}

// What the staff screen shows, built once from the same facts.
const ai = out(N.fallback).output || out(N.claude).output || null;
const cite = (id) => { const p = passages.find(x => x.chunk_id === id); return p ? p.doc_title + ' v' + p.version + ', ' + p.section_heading : id; };
const screen = ran(N.refused)
  ? { status: 'refused', owner_queue: null, staff_summary: 'Your role cannot submit intake items. Ask an admin for access.' }
  : ran(N.task)
    ? { status: 'routed', owner_queue: ai.owner_queue, staff_summary: ai.summary_for_staff, task_ref: out(N.task).id || out(N.task).task_id }
    : { status: 'in_review', owner_queue: 'human_review', staff_summary: 'Waiting for a person: ' + (out(N.review).reason || 'needs review') };
Object.assign(screen, {
  item_id: intake.item_id,
  next_steps: screen.status === 'routed' ? (ai.next_steps || []) : [],
  cited_sources: ai ? (ai.cited_chunk_ids || []).map(cite) : [],
  ai_model: out(N.fallback).output ? 'openai' : (ai ? 'claude' : null),
  ai_confidence: ai ? ai.confidence : null,
  audit_rows: rows.length,
});
return rows.map(r => ({ json: { ...r, screen } }));

